def get_scaffold_sequence(scaffold_type):
    """Get the geometry parameters based on the selected scaffold type."""
    if scaffold_type == "m13":
        return _get_m13mp18()
    elif scaffold_type == "p7308":
        return _get_p7308()
    elif scaffold_type == "p7560":
        return _get_p7560()
    elif scaffold_type == "p7704":
        return _get_p7704()
    elif scaffold_type == "p8064":
        return _get_p8064()
    elif scaffold_type == "p8100":
        return _get_p8100()
    elif scaffold_type == "p8634":
        return _get_p8634()
    else:
        raise ValueError("Invalid default scaffold type selected.")

# Below sequences are from cadnano to ensure sequence export from hado matches cadnano
# https://github.com/douglaslab/cadnano2/blob/239ecc851407b64b44a8a4bdecdd5eb4848868f5/cadnano2/data/dnasequences.py#L1

def _get_m13mp18():
    # NOTE: This does not exactly match the M13 provided by Bayou Biolabs as they rotate the start of their
    #       M13 to this portion of the scaffold: "AATGCTACTACTAT..."
    #       Overall, this discrepancy causes an issue when comparing output of hado to cadnano, so i use the same
    #       M13 as cadnano instead (which is same sequence as Bayou, just starts from a different rotation)
    sequence = ""
    return sequence

